export function getAirlineCodes(value = "") {
  const [marketingLogoCode = "", operatingCode = marketingLogoCode] =
    value.split("-");
  const marketingCode = marketingLogoCode.substring(0, 3);

  return {
    marketingCode,
    marketingLogoCode: marketingLogoCode || marketingCode,
    operatingCode: operatingCode.substring(0, 3),
  };
}

const EARTH_RADIUS_MILES = 3958.7613;

function toRadians(value) {
  return (value * Math.PI) / 180;
}

function hasCoordinates(airport = {}) {
  return Number.isFinite(airport.lat) && Number.isFinite(airport.lon);
}

function hasNumericMiles(value = "") {
  return /^\d+$/.test(String(value).trim());
}

export function calculateGreatCircleMiles(fromAirport = {}, toAirport = {}) {
  if (!hasCoordinates(fromAirport) || !hasCoordinates(toAirport)) {
    return null;
  }

  const latitudeDelta = toRadians(toAirport.lat - fromAirport.lat);
  const longitudeDelta = toRadians(toAirport.lon - fromAirport.lon);
  const fromLatitude = toRadians(fromAirport.lat);
  const toLatitude = toRadians(toAirport.lat);
  const haversine =
    Math.sin(latitudeDelta / 2) ** 2 +
    Math.cos(fromLatitude) *
      Math.cos(toLatitude) *
      Math.sin(longitudeDelta / 2) ** 2;
  const centralAngle =
    2 * Math.atan2(Math.sqrt(haversine), Math.sqrt(1 - haversine));

  return Math.round(EARTH_RADIUS_MILES * centralAngle);
}

function resolveMiles(value = "", calculatedMiles = null) {
  if (hasNumericMiles(value)) {
    return String(value).trim();
  }

  if (Number.isFinite(calculatedMiles)) {
    return String(calculatedMiles);
  }

  return "0";
}

export function getAirportDetails(code = "", airports = {}) {
  const airport = airports[code];

  if (!airport) {
    return {
      iata: code,
      icao: code,
      name: code,
      flagCode: "undefined",
    };
  }

  return {
    iata: code,
    ...airport,
  };
}

export function getRegistrationDetails(value = "") {
  const [countryCode = "", tailNumber = "", photoPath = ""] = value.split("|");

  return {
    countryCode,
    tailNumber,
    photoPath,
    isUnknown: tailNumber.includes("?"),
  };
}

export function buildCallSign(row, operatingCode) {
  if (row.CallSign) {
    return row.CallSign;
  }

  return `${operatingCode}${String(row.Flight || "").substring(2)}`;
}

export function normalizeFlightLogRow(row, index, options = {}) {
  const { airlines = {}, airports = {}, columns = [] } = options;
  const airlineCodes = getAirlineCodes(row.Airline);
  const registrationInfo = getRegistrationDetails(row.Registration);
  const fromAirport = getAirportDetails(row.From, airports);
  const toAirport = getAirportDetails(row.To, airports);
  const calculatedMiles = calculateGreatCircleMiles(fromAirport, toAirport);
  const marketingAirlineDisplayName =
    airlines[airlineCodes.marketingCode] || airlineCodes.marketingCode;
  const operatingAirlineDisplayName =
    airlines[airlineCodes.operatingCode] || airlineCodes.operatingCode;

  return {
    ...Object.fromEntries(columns.map((column) => [column, row[column] || ""])),
    id: `${row.Date}-${row.Flight}-${index}`,
    originalIndex: index,
    CallSign: buildCallSign(row, airlineCodes.operatingCode),
    Miles: resolveMiles(row.Miles, calculatedMiles),
    calculatedMiles,
    airlineDisplayName: marketingAirlineDisplayName,
    airlineLogoCode: airlineCodes.marketingLogoCode,
    marketingAirlineCode: airlineCodes.marketingCode,
    marketingAirlineDisplayName,
    operatingAirlineCode: airlineCodes.operatingCode,
    operatingAirlineDisplayName,
    fromAirport,
    toAirport,
    registrationInfo,
    imageUrl: registrationInfo.photoPath
      ? `https://cdn.jetphotos.com/full${registrationInfo.photoPath}`
      : "",
    previewImageUrl: registrationInfo.photoPath
      ? `https://cdn.jetphotos.com/400${registrationInfo.photoPath}`
      : "",
  };
}

export function sortFlightLogRows(rows, sortBy, sortOrder) {
  const direction = sortOrder === "asc" ? 1 : -1;

  return [...rows].sort((a, b) => {
    let comparison = 0;

    if (sortBy === "Miles") {
      comparison = Number(a.Miles) - Number(b.Miles);
    } else {
      comparison = String(a[sortBy] || "").localeCompare(
        String(b[sortBy] || ""),
      );
    }

    if (comparison !== 0) {
      return comparison * direction;
    }

    return a.originalIndex - b.originalIndex;
  });
}

function normalizeSearchValue(value = "") {
  return String(value).trim().toLowerCase();
}

function normalizeCompactToken(value = "") {
  return normalizeSearchValue(value).replace(/[^a-z0-9]+/g, "");
}

function addSearchTokenVariants(tokens, value) {
  const normalized = normalizeSearchValue(value);

  if (!normalized) {
    return;
  }

  tokens.add(normalized);

  const compact = normalizeCompactToken(normalized);

  if (compact && compact !== normalized) {
    tokens.add(compact);
  }

  normalized
    .split(/[^a-z0-9]+/)
    .filter(Boolean)
    .forEach((part) => {
      tokens.add(part);

      (part.match(/[a-z]+|\d+/g) || []).forEach((chunk) => {
        if (chunk.length > 1 || /\d/.test(chunk)) {
          tokens.add(chunk);
        }
      });
    });
}

function buildRouteToken(fromCode = "", toCode = "") {
  const from = normalizeCompactToken(fromCode);
  const to = normalizeCompactToken(toCode);

  if (!from || !to) {
    return "";
  }

  return `${from}-${to}`;
}

function getRouteSearchToken(value = "") {
  const match = normalizeSearchValue(value).match(
    /^([a-z0-9]{3,4})\s*-\s*([a-z0-9]{3,4})$/,
  );

  if (!match) {
    return "";
  }

  return buildRouteToken(match[1], match[2]);
}

function buildAircraftModelTokens(value = "") {
  const tokens = new Set();
  const normalized = normalizeSearchValue(value);

  if (!normalized) {
    return tokens;
  }

  const modelMatch = normalized.match(/([a-z]*\d{2,4}(?:-[a-z0-9]+)+)/);

  if (!modelMatch) {
    return tokens;
  }

  const fullModel = modelMatch[1].replace(/\(.*/, "");
  const numericModel = fullModel.replace(/^[a-z]+/, "");
  const [family = "", variant = ""] = numericModel.split("-");

  if (!family || !variant) {
    return tokens;
  }

  tokens.add(numericModel);

  for (let index = 1; index <= variant.length; index += 1) {
    tokens.add(`${family}-${variant.slice(0, index)}`);
  }

  return tokens;
}

function buildFlightLogSearchIndex(row) {
  const exactTokens = new Set();
  const aircraftModelTokens = new Set();
  const routeTokens = new Set();
  const looseText = [
    row.Date,
    row.Airline,
    row.airlineDisplayName,
    row.airlineLogoCode,
    row.marketingAirlineCode,
    row.marketingAirlineDisplayName,
    row.operatingAirlineCode,
    row.operatingAirlineDisplayName,
    row.Flight,
    row.CallSign,
    row.Aircraft,
    row.Registration,
    row.registrationInfo?.tailNumber,
    row.fromAirport?.iata,
    row.fromAirport?.icao,
    row.fromAirport?.name,
    row.toAirport?.iata,
    row.toAirport?.icao,
    row.toAirport?.name,
  ]
    .filter(Boolean)
    .map((value) => normalizeSearchValue(value))
    .join(" ");

  [
    row.Date,
    row.Airline,
    row.airlineDisplayName,
    row.airlineLogoCode,
    row.marketingAirlineCode,
    row.marketingAirlineDisplayName,
    row.operatingAirlineCode,
    row.operatingAirlineDisplayName,
    row.Flight,
    row.CallSign,
    row.Aircraft,
    row.Registration,
    row.registrationInfo?.tailNumber,
    row.fromAirport?.iata,
    row.fromAirport?.icao,
    row.fromAirport?.name,
    row.toAirport?.iata,
    row.toAirport?.icao,
    row.toAirport?.name,
  ].forEach((value) => addSearchTokenVariants(exactTokens, value));

  buildAircraftModelTokens(row.Aircraft).forEach((token) => {
    aircraftModelTokens.add(token);
    exactTokens.add(token);
  });

  [
    buildRouteToken(row.fromAirport?.iata, row.toAirport?.iata),
    buildRouteToken(row.fromAirport?.icao, row.toAirport?.icao),
  ]
    .filter(Boolean)
    .forEach((token) => {
      routeTokens.add(token);
      exactTokens.add(token);
    });

  return {
    aircraftModelTokens,
    exactTokens,
    looseText,
    routeTokens,
  };
}

function matchesSearchTerm(searchIndex, term) {
  const normalizedTerm = normalizeSearchValue(term);

  if (!normalizedTerm) {
    return true;
  }

  const routeToken = getRouteSearchToken(normalizedTerm);

  if (routeToken) {
    return searchIndex.routeTokens.has(routeToken);
  }

  const compactTerm = normalizeCompactToken(normalizedTerm);

  if (normalizedTerm.includes("-") && /\d/.test(normalizedTerm)) {
    return (
      searchIndex.exactTokens.has(normalizedTerm) ||
      searchIndex.aircraftModelTokens.has(normalizedTerm) ||
      (compactTerm && searchIndex.exactTokens.has(compactTerm))
    );
  }

  if (/[\d-]/.test(normalizedTerm)) {
    return (
      searchIndex.exactTokens.has(normalizedTerm) ||
      (compactTerm && searchIndex.exactTokens.has(compactTerm))
    );
  }

  return (
    searchIndex.exactTokens.has(normalizedTerm) ||
    searchIndex.looseText.includes(normalizedTerm)
  );
}

export function filterFlightLogRows(rows, filters = {}) {
  const { airline = "all", search = "", year = "all" } = filters;
  const normalizedSearch = normalizeSearchValue(search);
  const searchTerms = normalizedSearch.split(/\s+/).filter(Boolean);

  return rows.filter((row) => {
    if (airline !== "all" && row.marketingAirlineCode !== airline) {
      return false;
    }

    if (year !== "all" && String(row.Date || "").slice(0, 4) !== year) {
      return false;
    }

    if (!normalizedSearch) {
      return true;
    }

    const searchIndex = buildFlightLogSearchIndex(row);

    return searchTerms.every((term) => matchesSearchTerm(searchIndex, term));
  });
}

export function buildFlightLogSummary(rows, allRows = rows) {
  const miles = rows.reduce((sum, row) => sum + Number(row.Miles || 0), 0);
  const airports = new Set();
  const airlines = new Set();

  rows.forEach((row) => {
    if (row.fromAirport?.iata) {
      airports.add(row.fromAirport.iata);
    }
    if (row.toAirport?.iata) {
      airports.add(row.toAirport.iata);
    }
    if (row.marketingAirlineCode) {
      airlines.add(row.marketingAirlineCode);
    }
  });

  const latestFlight = [...rows].sort((a, b) =>
    String(b.Date || "").localeCompare(String(a.Date || "")),
  )[0]?.Date;

  return {
    airlinesCount: airlines.size,
    filteredFlights: rows.length,
    latestFlight: latestFlight || "N/A",
    totalAirports: airports.size,
    totalFlights: allRows.length,
    totalMiles: miles,
  };
}
