<script setup>
import { computed, onMounted } from "vue";

import FlightLogGallery from "@/components/flight-log/FlightLogGallery.vue";
import FlightLogMap from "@/components/flight-log/FlightLogMap.vue";
import FlightLogTable from "@/components/flight-log/FlightLogTable.vue";
import { useFlightLogData } from "@/composables/useFlightLogData";

const {
  activeView,
  airlineOptions,
  currentPage,
  filteredRows,
  goToPage,
  isGalleryView,
  isMapView,
  isIata,
  itemsPerPage,
  paginatedRows,
  searchQuery,
  selectedAirline,
  selectedYear,
  setSortColumn,
  setSortOrder,
  sortBy,
  sortOrder,
  sortOptions,
  sortableColumns,
  summary,
  toggleSortByColumn,
  totalPages,
  totalRows,
  visibleColumns,
  yearOptions,
} = useFlightLogData();

const rowStart = computed(() => (currentPage.value - 1) * itemsPerPage);
const shouldShowPagination = computed(() => !isMapView.value);

function formatNumber(value) {
  return new Intl.NumberFormat("en-US").format(value);
}

onMounted(() => {
  document.title = "Weili: Flight Log";
  window.scrollTo({
    top: 0,
    behavior: "smooth",
  });
});
</script>

<template>
  <div class="flightlog-page">
    <section class="summary-grid">
      <article class="summary-card surface-card surface-card--soft">
        <div class="summary-label">Flights</div>
        <div class="summary-value">
          {{ formatNumber(summary.filteredFlights) }}
        </div>
        <div class="summary-subtle">
          of {{ formatNumber(summary.totalFlights) }}
        </div>
      </article>

      <article class="summary-card surface-card surface-card--soft">
        <div class="summary-label">Miles</div>
        <div class="summary-value">
          {{ formatNumber(summary.totalMiles) }}
        </div>
        <div class="summary-subtle">in current results</div>
      </article>

      <article class="summary-card surface-card surface-card--soft">
        <div class="summary-label">Airlines</div>
        <div class="summary-value">
          {{ formatNumber(summary.airlinesCount) }}
        </div>
        <div class="summary-subtle">currently shown</div>
      </article>

      <article class="summary-card surface-card surface-card--soft">
        <div class="summary-label">Airports</div>
        <div class="summary-value">
          {{ formatNumber(summary.totalAirports) }}
        </div>
        <div class="summary-subtle">currently shown</div>
      </article>

      <article class="summary-card surface-card surface-card--soft">
        <div class="summary-label">Latest Flight</div>
        <div class="summary-value summary-value-date summary-value-latest">
          {{ summary.latestFlight }}
        </div>
        <div class="summary-subtle">most recent match</div>
      </article>
    </section>

    <section class="controls-panel surface-card">
      <div class="controls-row">
        <div class="ui-segmented">
          <button
            :class="['ui-segment-button', { active: activeView === 'table' }]"
            type="button"
            @click="activeView = 'table'"
          >
            Table
          </button>
          <button
            :class="['ui-segment-button', { active: activeView === 'gallery' }]"
            type="button"
            @click="activeView = 'gallery'"
          >
            Gallery
          </button>
          <button
            :class="['ui-segment-button', { active: activeView === 'map' }]"
            type="button"
            @click="activeView = 'map'"
          >
            Map
          </button>
        </div>

        <div class="ui-segmented">
          <button
            :class="['ui-segment-button', { active: isIata }]"
            type="button"
            @click="isIata = true"
          >
            IATA
          </button>
          <button
            :class="['ui-segment-button', { active: !isIata }]"
            type="button"
            @click="isIata = false"
          >
            ICAO
          </button>
        </div>
      </div>

      <div
        :class="[
          'controls-grid',
          { 'controls-grid--map': activeView === 'map' },
        ]"
      >
        <label class="control-group control-search">
          <span class="control-label ui-label">Search</span>
          <input
            v-model.trim="searchQuery"
            class="control-input ui-input"
            placeholder="Flight, reg, route, airline, aircraft"
            type="search"
          />
        </label>

        <label class="control-group">
          <span class="control-label ui-label">Airline</span>
          <select v-model="selectedAirline" class="control-input ui-input">
            <option
              v-for="option in airlineOptions"
              :key="option.value"
              :value="option.value"
            >
              {{ option.label }}
            </option>
          </select>
        </label>

        <label class="control-group">
          <span class="control-label ui-label">Year</span>
          <select v-model="selectedYear" class="control-input ui-input">
            <option
              v-for="option in yearOptions"
              :key="option.value"
              :value="option.value"
            >
              {{ option.label }}
            </option>
          </select>
        </label>

        <label v-if="!isMapView" class="control-group">
          <span class="control-label ui-label">Sort By</span>
          <select
            :value="sortBy"
            class="control-input ui-input"
            @change="setSortColumn($event.target.value)"
          >
            <option
              v-for="option in sortOptions"
              :key="option.value"
              :value="option.value"
            >
              {{ option.label }}
            </option>
          </select>
        </label>

        <label v-if="!isMapView" class="control-group">
          <span class="control-label ui-label">Order</span>
          <select
            :value="sortOrder"
            class="control-input ui-input"
            @change="setSortOrder($event.target.value)"
          >
            <option value="desc">Descending</option>
            <option value="asc">Ascending</option>
          </select>
        </label>
      </div>
    </section>

    <div v-if="shouldShowPagination" class="pagination-controls">
      <div class="results-meta">
        Showing {{ formatNumber(filteredRows.length) }} result<span
          v-if="filteredRows.length !== 1"
          >s</span
        >
        <span v-if="filteredRows.length !== totalRows">
          from {{ formatNumber(totalRows) }}
        </span>
      </div>

      <div class="pagination-buttons">
        <button
          class="ui-pill-button"
          :disabled="currentPage === 1"
          @click="goToPage(currentPage - 1)"
        >
          &lt;
        </button>

        <button
          v-for="page in totalPages"
          :key="page"
          :class="['ui-pill-button', { 'is-active': currentPage === page }]"
          @click="goToPage(page)"
        >
          {{ page }}
        </button>

        <button
          class="ui-pill-button"
          :disabled="currentPage === totalPages"
          @click="goToPage(currentPage + 1)"
        >
          &gt;
        </button>
      </div>
    </div>

    <div class="ft-container">
      <div class="table-wrapper">
        <div v-if="filteredRows.length === 0" class="empty-state">
          No flights match the current filters.
        </div>

        <FlightLogGallery
          v-else-if="isGalleryView"
          :is-iata="isIata"
          :rows="paginatedRows"
        />

        <FlightLogMap
          v-else-if="isMapView"
          :is-iata="isIata"
          :rows="filteredRows"
        />

        <FlightLogTable
          v-else
          :columns="visibleColumns"
          :is-iata="isIata"
          :row-start="rowStart"
          :rows="paginatedRows"
          :sort-by="sortBy"
          :sort-order="sortOrder"
          :sortable-columns="sortableColumns"
          @sort="toggleSortByColumn"
        />
      </div>
    </div>
  </div>
