import Papa from "papaparse";

import { blob } from "@/assets/blob.js";
import { AIRLINES, AIRPORTS, FLIGHT_LOG_COLUMNS } from "@/constants/flightLog";
import {
  buildFlightLogSummary,
  filterFlightLogRows,
  normalizeFlightLogRow,
  sortFlightLogRows,
} from "./flightLogCore.mjs";

const FLIGHT_LOG_CSV = atob(blob);

export function getFlightLogRows() {
  const { data } = Papa.parse(FLIGHT_LOG_CSV, {
    header: true,
    skipEmptyLines: true,
  });

  return data.map((row, index) =>
    normalizeFlightLogRow(row, index, {
      airlines: AIRLINES,
      airports: AIRPORTS,
      columns: FLIGHT_LOG_COLUMNS,
    }),
  );
}

export function getAirlineLogoSrc(code) {
  return require(`@/assets/airlines/${code}.png`);
}

export function getFlagSrc(code) {
  if (!code || code === "?" || code === "undefined") {
    return require("@/assets/flag/undefined.png");
  }

  return require(`@/assets/flag/${code.toLowerCase()}.svg`);
}

export { sortFlightLogRows };
export { filterFlightLogRows };
export { buildFlightLogSummary };
