<script setup>
/* eslint-env vue/setup-compiler-macros */
import { computed, ref, watch } from "vue";

import worldLandGeoJson from "@/assets/map/ne_110m_land.js";
import {
  buildFlightMapData,
  buildGeoJsonFeaturePaths,
  buildRouteGroupId,
  FLIGHT_MAP_DIMENSIONS,
} from "@/utils/flightLogMap.mjs";

const props = defineProps({
  isIata: {
    type: Boolean,
    required: true,
  },
  rows: {
    type: Array,
    required: true,
  },
});

const meridians = [-120, -60, 0, 60, 120, 180];
const parallels = [-40, -20, 0, 20, 40, 60];
const MIN_ZOOM = 1;
const MAX_ZOOM = 10;
const BUTTON_ZOOM_STEP = 1.18;
const WHEEL_ZOOM_SENSITIVITY = 0.00075;
const HORIZONTAL_WORLD_TILE_OFFSETS = [-1, 0, 1];
const MAP_WRAP_WIDTH =
  FLIGHT_MAP_DIMENSIONS.width - FLIGHT_MAP_DIMENSIONS.paddingX * 2;

const worldLandPaths = buildGeoJsonFeaturePaths(
  worldLandGeoJson,
  FLIGHT_MAP_DIMENSIONS,
);

const selectedAirportCode = ref("");
const selectedRouteGroupId = ref("");
const activeSidebarPanel = ref("route");
const mapShell = ref(null);
const isDragging = ref(false);
const zoom = ref(1);
const viewCenter = ref({
  x: FLIGHT_MAP_DIMENSIONS.width / 2,
  y: FLIGHT_MAP_DIMENSIONS.height / 2,
});
const dragState = ref(null);
const expandedDirections = ref({});

const mapData = computed(() =>
  buildFlightMapData(props.rows, FLIGHT_MAP_DIMENSIONS),
);
const worldTileOffsets = computed(() =>
  HORIZONTAL_WORLD_TILE_OFFSETS.map(
    (multiplier) => multiplier * MAP_WRAP_WIDTH,
  ),
);
const latitudeLabelX = computed(() => getCurrentViewport().x + 10 / zoom.value);
const longitudeLabelY = computed(
  () => getCurrentViewport().y + getCurrentViewport().height - 10 / zoom.value,
);
const currentViewBox = computed(() => {
  const viewportWidth = FLIGHT_MAP_DIMENSIONS.width / zoom.value;
  const viewportHeight = FLIGHT_MAP_DIMENSIONS.height / zoom.value;
  const center = clampViewCenter(
    viewCenter.value.x,
    viewCenter.value.y,
    zoom.value,
  );

  return [
    center.x - viewportWidth / 2,
    center.y - viewportHeight / 2,
    viewportWidth,
    viewportHeight,
  ].join(" ");
});

const selectedRoute = computed(
  () =>
    mapData.value.routeGroups.find(
      (route) => route.id === selectedRouteGroupId.value,
    ) ||
    mapData.value.routeGroups[0] ||
    null,
);

const selectedAirport = computed(
  () =>
    mapData.value.airports.find(
      (airport) => airport.iata === selectedAirportCode.value,
    ) ||
    mapData.value.busiestAirport ||
    null,
);

watch(
  mapData,
  (data) => {
    if (
      !data.routeGroups.some((route) => route.id === selectedRouteGroupId.value)
    ) {
      selectedRouteGroupId.value = data.routeGroups[0]?.id || "";
    }

    if (
      !data.airports.some(
        (airport) => airport.iata === selectedAirportCode.value,
      )
    ) {
      selectedAirportCode.value = data.airports[0]?.iata || "";
    }
  },
  { immediate: true },
);

watch(selectedRouteGroupId, () => {
  expandedDirections.value = {};
});

function formatNumber(value) {
  return new Intl.NumberFormat("en-US").format(value);
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function wrapHorizontal(value, width = MAP_WRAP_WIDTH) {
  return ((value % width) + width) % width;
}

function getViewportSize(level = zoom.value) {
  return {
    width: FLIGHT_MAP_DIMENSIONS.width / level,
    height: FLIGHT_MAP_DIMENSIONS.height / level,
  };
}

function clampViewCenter(x, y, level = zoom.value) {
  const viewport = getViewportSize(level);

  return {
    x: wrapHorizontal(x),
    y: clamp(
      y,
      viewport.height / 2,
      FLIGHT_MAP_DIMENSIONS.height - viewport.height / 2,
    ),
  };
}

function getWrappedViewportX(pointX, viewport, margin = 0) {
  return [pointX - MAP_WRAP_WIDTH, pointX, pointX + MAP_WRAP_WIDTH].find(
    (candidateX) =>
      candidateX >= viewport.x - margin &&
      candidateX <= viewport.x + viewport.width + margin,
  );
}

function getCurrentViewport() {
  const viewport = getViewportSize(zoom.value);
  const center = clampViewCenter(
    viewCenter.value.x,
    viewCenter.value.y,
    zoom.value,
  );

  return {
    x: center.x - viewport.width / 2,
    y: center.y - viewport.height / 2,
    width: viewport.width,
    height: viewport.height,
  };
}

const labeledAirports = computed(() => {
  const viewport = getCurrentViewport();
  const labelLimit = Math.round(clamp(12 + (zoom.value - 1) * 6, 12, 30));
  const minimumHorizontalGap = 82 / zoom.value;
  const minimumVerticalGap = 22 / zoom.value;
  const viewportMargin = 18 / zoom.value;
  const selectedLabels = [];

  for (const airport of mapData.value.airports) {
    if (!airport.point) {
      continue;
    }

    const pointX = getWrappedViewportX(
      airport.point.x,
      viewport,
      viewportMargin,
    );

    if (
      pointX === undefined ||
      airport.point.y < viewport.y - viewportMargin ||
      airport.point.y > viewport.y + viewport.height + viewportMargin
    ) {
      continue;
    }

    const labelPoint = {
      x: airportLabelX(airport, pointX),
      y: airport.point.y,
    };

    const overlaps = selectedLabels.some(
      (existing) =>
        Math.abs(existing.x - labelPoint.x) < minimumHorizontalGap &&
        Math.abs(existing.y - labelPoint.y) < minimumVerticalGap,
    );

    if (overlaps) {
      continue;
    }

    selectedLabels.push({
      ...airport,
      labelPoint,
    });

    if (selectedLabels.length >= labelLimit) {
      break;
    }
  }

  return selectedLabels;
});

function getSvgCoordinates(clientX, clientY) {
  const rect = mapShell.value?.getBoundingClientRect();

  if (!rect || rect.width === 0 || rect.height === 0) {
    return null;
  }

  const viewport = getCurrentViewport();
  const relativeX = clamp((clientX - rect.left) / rect.width, 0, 1);
  const relativeY = clamp((clientY - rect.top) / rect.height, 0, 1);

  return {
    relativeX,
    relativeY,
    x: viewport.x + relativeX * viewport.width,
    y: viewport.y + relativeY * viewport.height,
  };
}

function setZoom(nextZoom, anchor = null) {
  const boundedZoom = clamp(nextZoom, MIN_ZOOM, MAX_ZOOM);

  if (boundedZoom === zoom.value) {
    return;
  }

  if (anchor) {
    const nextViewport = getViewportSize(boundedZoom);
    const nextCenter = clampViewCenter(
      anchor.x + nextViewport.width / 2 - anchor.relativeX * nextViewport.width,
      anchor.y +
        nextViewport.height / 2 -
        anchor.relativeY * nextViewport.height,
      boundedZoom,
    );

    zoom.value = boundedZoom;
    viewCenter.value = nextCenter;
    return;
  }

  zoom.value = boundedZoom;
  viewCenter.value = clampViewCenter(
    viewCenter.value.x,
    viewCenter.value.y,
    boundedZoom,
  );
}

function zoomIn() {
  setZoom(zoom.value * BUTTON_ZOOM_STEP);
}

function zoomOut() {
  setZoom(zoom.value / BUTTON_ZOOM_STEP);
}

function resetView() {
  zoom.value = 1;
  viewCenter.value = {
    x: FLIGHT_MAP_DIMENSIONS.width / 2,
    y: FLIGHT_MAP_DIMENSIONS.height / 2,
  };
}

function startPan(event) {
  if (event.pointerType === "mouse" && event.button !== 0) {
    return;
  }

  const rect = mapShell.value?.getBoundingClientRect();

  if (!rect) {
    return;
  }

  dragState.value = {
    pointerId: event.pointerId,
    clientX: event.clientX,
    clientY: event.clientY,
    centerX: viewCenter.value.x,
    centerY: viewCenter.value.y,
    rectWidth: rect.width,
    rectHeight: rect.height,
  };
  isDragging.value = true;
  event.currentTarget.setPointerCapture?.(event.pointerId);
}

function continuePan(event) {
  if (!dragState.value || dragState.value.pointerId !== event.pointerId) {
    return;
  }

  const viewport = getViewportSize(zoom.value);
  const deltaX =
    ((event.clientX - dragState.value.clientX) / dragState.value.rectWidth) *
    viewport.width;
  const deltaY =
    ((event.clientY - dragState.value.clientY) / dragState.value.rectHeight) *
    viewport.height;

  viewCenter.value = clampViewCenter(
    dragState.value.centerX - deltaX,
    dragState.value.centerY - deltaY,
  );
}

function endPan(event) {
  if (!dragState.value) {
    return;
  }

  if (!event || dragState.value.pointerId === event.pointerId) {
    event?.currentTarget?.releasePointerCapture?.(event.pointerId);
    dragState.value = null;
    isDragging.value = false;
  }
}

function handleWheel(event) {
  const anchor = getSvgCoordinates(event.clientX, event.clientY);

  if (!anchor) {
    return;
  }

  event.preventDefault();
  const zoomFactor = Math.exp(-event.deltaY * WHEEL_ZOOM_SENSITIVITY);
  setZoom(zoom.value * zoomFactor, anchor);
}

function getAirportCode(airport) {
  return props.isIata ? airport.iata : airport.icao;
}

function getFlightCode(row) {
  return props.isIata ? row.Flight : row.CallSign;
}

function getSelectedRouteCode(route) {
  return `${getAirportCode(route.fromAirport)}-${getAirportCode(
    route.toAirport,
  )}`;
}

function getConnectionCode(connection) {
  const airport = mapData.value.airports.find(
    (entry) => entry.iata === connection.code,
  );

  return airport ? getAirportCode(airport) : connection.code;
}

function getAirportLabel(airport) {
  return `${getAirportCode(airport)} ${airport.name}`;
}

function formatLongitudeLabel(value) {
  if (value === 0) {
    return "0°";
  }

  if (Math.abs(value) === 180) {
    return "180°";
  }

  return `${Math.abs(value)}°${value < 0 ? "W" : "E"}`;
}

function formatLatitudeLabel(value) {
  if (value === 0) {
    return "0°";
  }

  return `${Math.abs(value)}°${value < 0 ? "S" : "N"}`;
}

function routeStrokeOpacity(route) {
  if (selectedRoute.value?.id === route.id) {
    return 1;
  }

  return Math.min(0.68, 0.2 + route.flightCount * 0.08);
}

function getRenderedRouteStrokeWidth(route) {
  return route.strokeWidth / Math.pow(zoom.value, 0.22);
}

function getRenderedAirportRadius(airport) {
  return airport.radius / zoom.value;
}

function getRenderedAirportStrokeWidth() {
  return 1.35 / zoom.value;
}

function getAirportHitRadius(airport) {
  return Math.max(
    getRenderedAirportRadius(airport) + 2.5 / zoom.value,
    8 / zoom.value,
  );
}

function airportLabelX(airport, pointX = airport.point.x) {
  const radius = getRenderedAirportRadius(airport);

  if (airport.labelSide === "left") {
    return pointX - radius - 7 / zoom.value;
  }

  return pointX + radius + 7 / zoom.value;
}

function airportLabelAnchor(airport) {
  return airport.labelSide === "left" ? "end" : "start";
}

function getAirportLabelSize() {
  return 12.5 / zoom.value;
}

function getAirportLabelHitSize() {
  return 18 / zoom.value;
}

function getGraticuleLabelSize() {
  return 12;
}

function getLongitudeX(longitude) {
  return (
    mapData.value.dimensions.paddingX +
    ((longitude + 180) / 360) *
      (mapData.value.dimensions.width - mapData.value.dimensions.paddingX * 2)
  );
}

function getLatitudeY(latitude) {
  return (
    mapData.value.dimensions.paddingY +
    ((mapData.value.dimensions.maxLatitude - latitude) /
      (mapData.value.dimensions.maxLatitude -
        mapData.value.dimensions.minLatitude)) *
      (mapData.value.dimensions.height - mapData.value.dimensions.paddingY * 2)
  );
}

function getCoordinateLabelTransform(x, y) {
  const scale = 1 / zoom.value;

  return `translate(${x} ${y}) scale(${scale}) translate(${-x} ${-y})`;
}

function selectAirportConnection(connection) {
  if (!selectedAirport.value) {
    return;
  }

  selectRoute(buildRouteGroupId(selectedAirport.value.iata, connection.code));
}

function selectRoute(routeId) {
  selectedRouteGroupId.value = routeId;
  activeSidebarPanel.value = "route";
}

function focusAirport(airportId) {
  selectedAirportCode.value = airportId;
  activeSidebarPanel.value = "airport";
}

function getDirectionLabel(direction) {
  return `${getAirportCode(direction.fromAirport)}-${getAirportCode(
    direction.toAirport,
  )}`;
}

function getDirectionKicker(direction) {
  return `${direction.flightCount} flights · ${formatNumber(
    direction.averageMiles,
  )} mi avg`;
}

function isDirectionExpanded(directionId) {
  return Boolean(expandedDirections.value[directionId]);
}

function toggleDirection(directionId) {
  expandedDirections.value = {
    ...expandedDirections.value,
    [directionId]: !expandedDirections.value[directionId],
  };
}

function getVisibleDirectionRows(direction) {
  return isDirectionExpanded(direction.id)
    ? direction.rows
    : direction.rows.slice(0, 4);
}
</script>

<template>
  <div class="map-view">
    <section class="map-panel surface-card">
      <div class="map-header">
        <div>
          <div class="map-kicker">Route Network</div>
          <h3 class="map-title">Flights plotted from the current results</h3>
        </div>

        <div class="map-stats">
          <div class="map-stat">
            <span class="map-stat-label">Routes</span>
            <strong>{{ formatNumber(mapData.routeGroups.length) }}</strong>
          </div>
          <div class="map-stat">
            <span class="map-stat-label">Airports</span>
            <strong>{{ formatNumber(mapData.airports.length) }}</strong>
          </div>
          <div class="map-stat">
            <span class="map-stat-label">Miles</span>
            <strong>{{ formatNumber(mapData.totalMiles) }}</strong>
          </div>
        </div>
      </div>

      <div
        ref="mapShell"
        :class="['map-canvas-shell', { 'is-dragging': isDragging }]"
        @pointerdown="startPan"
        @pointermove="continuePan"
        @pointerup="endPan"
        @pointercancel="endPan"
        @pointerleave="endPan"
        @wheel="handleWheel"
      >
        <div class="map-controls">
          <button
            class="map-control-button"
            type="button"
            @pointerdown.stop
            @click.stop="zoomIn"
          >
            +
          </button>
          <button
            class="map-control-button"
            type="button"
            @pointerdown.stop
            @click.stop="zoomOut"
          >
            -
          </button>
          <button
            class="map-control-button map-control-button--wide"
            type="button"
            @pointerdown.stop
            @click.stop="resetView"
          >
            Reset
          </button>
        </div>

        <svg
          :viewBox="currentViewBox"
          class="route-map"
          aria-label="Route map"
          role="img"
        >
          <defs>
            <linearGradient
              id="routeMapOcean"
              x1="0%"
              y1="0%"
              x2="100%"
              y2="100%"
            >
              <stop offset="0%" stop-color="#0f2d3b" />
              <stop offset="45%" stop-color="#11485d" />
              <stop offset="100%" stop-color="#0b2230" />
            </linearGradient>
            <radialGradient id="routeMapBloom" cx="38%" cy="18%" r="75%">
              <stop offset="0%" stop-color="rgba(120, 220, 209, 0.18)" />
              <stop offset="48%" stop-color="rgba(255, 214, 154, 0.07)" />
              <stop offset="100%" stop-color="rgba(0, 0, 0, 0)" />
            </radialGradient>
            <linearGradient
              id="routeMapGlow"
              x1="0%"
              y1="0%"
              x2="100%"
              y2="100%"
            >
              <stop offset="0%" stop-color="#ffd47a" />
              <stop offset="50%" stop-color="#ff9f6b" />
              <stop offset="100%" stop-color="#ff785a" />
            </linearGradient>
          </defs>

          <rect
            :x="-MAP_WRAP_WIDTH"
            y="0"
            :width="mapData.dimensions.width + MAP_WRAP_WIDTH * 2"
            :height="mapData.dimensions.height"
            class="map-background"
          />
          <rect
            :x="-MAP_WRAP_WIDTH"
            y="0"
            :width="mapData.dimensions.width + MAP_WRAP_WIDTH * 2"
            :height="mapData.dimensions.height"
            class="map-bloom"
          />

          <g
            v-for="tileOffset in worldTileOffsets"
            :key="`world-tile-${tileOffset}`"
            :transform="`translate(${tileOffset} 0)`"
          >
            <g class="land-layer">
              <path
                v-for="(landPath, index) in worldLandPaths"
                :key="`land-${index}`"
                :d="landPath"
                class="land-mass"
              />
            </g>

            <g class="graticule-layer">
              <line
                v-for="longitude in meridians"
                :key="`lon-${longitude}`"
                :x1="getLongitudeX(longitude)"
                :x2="getLongitudeX(longitude)"
                :y1="mapData.dimensions.paddingY"
                :y2="mapData.dimensions.height - mapData.dimensions.paddingY"
                class="graticule-line"
              />

              <line
                v-for="latitude in parallels"
                :key="`lat-${latitude}`"
                :x1="mapData.dimensions.paddingX"
                :x2="mapData.dimensions.width - mapData.dimensions.paddingX"
                :y1="getLatitudeY(latitude)"
                :y2="getLatitudeY(latitude)"
                class="graticule-line"
              />
            </g>

            <g class="route-layer">
              <template v-for="route in mapData.routeGroups" :key="route.id">
                <path
                  v-for="(pathData, pathIndex) in route.paths"
                  :key="`${route.id}-${pathIndex}`"
                  :d="pathData"
                  :class="[
                    'route-stroke',
                    {
                      'is-selected':
                        selectedRoute && selectedRoute.id === route.id,
                    },
                  ]"
                  :opacity="routeStrokeOpacity(route)"
                  :stroke-width="getRenderedRouteStrokeWidth(route)"
                  tabindex="0"
                  @pointerdown.stop
                  @click.stop="selectRoute(route.id)"
                  @focus="selectRoute(route.id)"
                >
                  <title>
                    {{ getSelectedRouteCode(route) }} ·
                    {{ route.flightCount }} flights
                  </title>
                </path>
              </template>
            </g>

            <g class="airport-layer">
              <g
                v-for="airport in mapData.airports"
                :key="airport.iata"
                class="airport-node"
                @pointerdown.stop
                @click.stop="focusAirport(airport.iata)"
              >
                <circle
                  :cx="airport.point.x"
                  :cy="airport.point.y"
                  :r="getAirportHitRadius(airport)"
                  class="airport-hit-area"
                />
                <circle
                  :cx="airport.point.x"
                  :cy="airport.point.y"
                  :r="getRenderedAirportRadius(airport)"
                  :stroke-width="getRenderedAirportStrokeWidth()"
                  :class="[
                    'airport-dot',
                    {
                      'is-selected':
                        selectedAirport &&
                        selectedAirport.iata === airport.iata,
                    },
                  ]"
                >
                  <title>
                    {{ getAirportLabel(airport) }} ·
                    {{ airport.totalFlights }} flights
                  </title>
                </circle>
              </g>

              <g
                v-for="airport in labeledAirports"
                :key="`label-${airport.iata}`"
              >
                <text
                  :x="airport.labelPoint.x"
                  :y="airport.point.y + 4 / zoom"
                  :font-size="getAirportLabelSize()"
                  :text-anchor="airportLabelAnchor(airport)"
                  :stroke-width="getAirportLabelHitSize()"
                  class="airport-label-hit-area"
                  @pointerdown.stop
                  @click.stop="focusAirport(airport.iata)"
                >
                  {{ getAirportCode(airport) }}
                </text>
                <text
                  :x="airport.labelPoint.x"
                  :y="airport.point.y + 4 / zoom"
                  :font-size="getAirportLabelSize()"
                  :text-anchor="airportLabelAnchor(airport)"
                  class="airport-label"
                  @pointerdown.stop
                  @click.stop="focusAirport(airport.iata)"
                >
                  {{ getAirportCode(airport) }}
                </text>
              </g>
            </g>
          </g>

          <g class="graticule-layer">
            <template
              v-for="tileOffset in worldTileOffsets"
              :key="`lon-label-overlay-${tileOffset}`"
            >
              <text
                v-for="longitude in meridians"
                :key="`lon-label-overlay-${tileOffset}-${longitude}`"
                :x="getLongitudeX(longitude) + tileOffset"
                :y="longitudeLabelY"
                :transform="
                  getCoordinateLabelTransform(
                    getLongitudeX(longitude) + tileOffset,
                    longitudeLabelY,
                  )
                "
                class="graticule-label"
                :font-size="getGraticuleLabelSize()"
                text-anchor="middle"
              >
                {{ formatLongitudeLabel(longitude) }}
              </text>
            </template>

            <text
              v-for="latitude in parallels"
              :key="`lat-label-fixed-${latitude}`"
              :x="latitudeLabelX"
              :y="getLatitudeY(latitude) + 4"
              :transform="
                getCoordinateLabelTransform(
                  latitudeLabelX,
                  getLatitudeY(latitude) + 4,
                )
              "
              class="graticule-label"
              :font-size="getGraticuleLabelSize()"
            >
              {{ formatLatitudeLabel(latitude) }}
            </text>
          </g>
        </svg>
      </div>

      <div class="map-legend">
        <span
          >Wheel to zoom. Drag to pan. The world wraps horizontally. Reset snaps
          back to the full world view.</span
        >
        <span>Route thickness scales with repeat flights.</span>
        <span
          >Airport dots scale with total departures and arrivals in the
          filter.</span
        >
      </div>
    </section>

    <aside class="map-sidebar">
      <section class="sidebar-card surface-card surface-card--soft">
        <div class="sidebar-header">
          <div>
            <h3 class="sidebar-title">
              {{
                activeSidebarPanel === "route" ? "Route View" : "Airport View"
              }}
            </h3>
          </div>
          <div class="ui-segmented sidebar-segmented">
            <button
              :class="[
                'ui-segment-button',
                { active: activeSidebarPanel === 'route' },
              ]"
              type="button"
              @click="activeSidebarPanel = 'route'"
            >
              Route
            </button>
            <button
              :class="[
                'ui-segment-button',
                { active: activeSidebarPanel === 'airport' },
              ]"
              type="button"
              @click="activeSidebarPanel = 'airport'"
            >
              Airport
            </button>
          </div>
        </div>

        <template v-if="activeSidebarPanel === 'route' && selectedRoute">
          <div class="sidebar-kicker sidebar-kicker--spaced">
            Selected Route
          </div>
          <h4 class="sidebar-subtitle-title">
            {{ getSelectedRouteCode(selectedRoute) }}
          </h4>
          <div class="sidebar-meta">
            <span>{{ selectedRoute.flightCount }} flights</span>
            <span
              >{{ formatNumber(selectedRoute.averageMiles) }} avg miles</span
            >
          </div>
          <div class="sidebar-tags">
            <span
              v-for="airline in selectedRoute.airlines"
              :key="airline"
              class="sidebar-tag"
            >
              {{ airline }}
            </span>
          </div>
          <div class="sidebar-section-title">Flights by direction</div>
          <div class="direction-groups">
